/* Actual unelevated panel -> authenticated elevated worker -> real NTFS cache.
 * Drives only owned UI messages and a fresh caller-supplied fixture directory. */
#include "../app/space.h"
static int observed_record(sp_model *,const sp_record *,const wchar_t *);
#define space_model_record observed_record
#define wWinMain ntfs_unused_panel_entrypoint
#include "../app/fpspace.c"
#undef wWinMain
#undef space_model_record
static int passed,failed;static volatile LONG cached_seen,resets;static wchar_t fixture[32768];
#define CHECK(label,x) do{if(x){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL %d %s\n",__LINE__,label);}}while(0)
static int observed_record(sp_model *m,const sp_record *r,const wchar_t *name){if(r->type==SP_STATUS&&r->flags==NTFS_CACHED)InterlockedIncrement(&cached_seen);if(r->type==SP_RESET)InterlockedIncrement(&resets);return space_model_record(m,r,name);}
static void pump(unsigned ms){uint64_t end=GetTickCount64()+ms,next=GetTickCount64();while(GetTickCount64()<end){MSG msg;while(PeekMessageW(&msg,NULL,0,0,PM_REMOVE))if(msg.message!=WM_QUIT){TranslateMessage(&msg);DispatchMessageW(&msg);}if(GetTickCount64()>=next){tick();next=GetTickCount64()+200;}Sleep(5);}}
static int query_wait(void){uint64_t until=GetTickCount64()+10000;while(GetTickCount64()<until){tick();if(!A.query&&!A.query_pending&&!(A.view&&A.dirty))return !A.query_error;pump(20);}return 0;}
static int live_wait(unsigned ms){uint64_t end=GetTickCount64()+ms;while(GetTickCount64()<end){EnterCriticalSection(&A.lock);int live=A.model.backend==SP_BACKEND_NTFS&&A.model.phase==NTFS_LIVE&&A.model.state==SP_COMPLETE&&A.model.count;int fallback=A.model.phase==NTFS_FALLBACK;LeaveCriticalSection(&A.lock);if(live)return 1;if(fallback)break;pump(200);}fprintf(stderr,"NTFS wait backend=%u phase=%u state=%u error=%u backend_error=%u count=%u\n",A.model.backend,A.model.phase,A.model.state,A.model.error,A.model.backend_error,A.model.count);return 0;}
static void path_for_fixture(wchar_t *path,const wchar_t *name){swprintf(path,32768,L"%ls\\%ls",fixture,name);}
static int write_fixture(const wchar_t *name,DWORD n){wchar_t path[32768];path_for_fixture(path,name);HANDLE f=CreateFileW(path,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,NULL,CREATE_ALWAYS,0,NULL);if(f==INVALID_HANDLE_VALUE)return 0;uint8_t bytes[65536]={0};DWORD written=0;int ok=n<=sizeof bytes&&WriteFile(f,bytes,n,&written,NULL)&&written==n;CloseHandle(f);return ok;}
static uint32_t find_fixture(void){const wchar_t *name=wcsrchr(fixture,L'\\');name=name?name+1:fixture;for(uint32_t i=0;i<A.model.count;i++)if(A.model.nodes[i].flags&SP_DIR&&!(A.model.nodes[i].flags&SP_REMOVED)&&!wcscmp(A.model.nodes[i].name,name)){wchar_t *path=space_model_path(&A.model,i,L"C:\\");int same=path&&!_wcsicmp(path,fixture);free(path);if(same)return i;}return SP_NONE;}
static uint32_t child(uint32_t parent,const wchar_t *name){if(parent>=A.model.count)return SP_NONE;for(uint32_t i=A.model.nodes[parent].first;i!=SP_NONE;i=A.model.nodes[i].next)if(!(A.model.nodes[i].flags&SP_REMOVED)&&!wcscmp(A.model.nodes[i].name,name))return i;return SP_NONE;}
static int wait_size(uint32_t parent,const wchar_t *name,uint64_t size,unsigned ms){uint64_t end=GetTickCount64()+ms;while(GetTickCount64()<end){EnterCriticalSection(&A.lock);uint32_t id=child(parent,name);int okay=id<A.model.count&&A.model.nodes[id].sum.logical==size;LeaveCriticalSection(&A.lock);if(okay)return 1;pump(200);}return 0;}
static void test_ntfs_panel_initial_model_and_views(void){space_open request={.session=987};uint64_t start=GetTickCount64();queue_root(L"C:\\",&request);CHECK("whole-volume analyzer starts owned worker",A.thread!=NULL);CHECK("actual NTFS worker publishes full model",live_wait(180000));printf("initial_ready_ms=%llu count=%u\n",(unsigned long long)(GetTickCount64()-start),A.model.count);if(A.model.backend!=SP_BACKEND_NTFS||A.model.phase!=NTFS_LIVE)return;
 EnterCriticalSection(&A.lock);uint32_t root=find_fixture(),file=child(root,L"normal.bin"),alias=child(root,L"alias.bin");if(root<A.model.count&&(file>=A.model.count||alias>=A.model.count)){fwprintf(stderr,L"fixture children root=%u file=%u alias=%u path=%ls\n",root,file,alias,fixture);for(uint32_t x=A.model.nodes[root].first;x!=SP_NONE;x=A.model.nodes[x].next)fwprintf(stderr,L"child %u flags=%u name=%ls\n",x,A.model.nodes[x].flags,A.model.nodes[x].name);}CHECK("owned tree exists in whole-volume result",root<A.model.count&&file<A.model.count&&alias<A.model.count);CHECK("hard links retain logical entries and unique storage",root<A.model.count&&A.model.nodes[root].sum.logical==131075&&A.model.nodes[root].sum.allocated==65536&&A.model.nodes[root].sum.hardlinks==1);LeaveCriticalSection(&A.lock);if(root>=A.model.count)return;scope(root);activate(11,0);CHECK("background largest query completes",query_wait());CHECK("largest-files view queries cached owned subtree",A.view==1&&A.count==3);activate(12,0);CHECK("background type query completes",query_wait());CHECK("file-type view works on NTFS results",A.count>=2);activate(10,0);CHECK("folder view restores captured scope",A.scope==root&&A.count==3);}
static void test_ntfs_panel_live_updates_and_hidden_pause(void){EnterCriticalSection(&A.lock);uint32_t root=find_fixture(),id=child(root,L"normal.bin");LeaveCriticalSection(&A.lock);if(root>=A.model.count){CHECK("initial NTFS fixture required",0);return;}LONG before=resets;CHECK("owned file changes",write_fixture(L"normal.bin",16384));CHECK("USN update reaches existing panel model",wait_size(root,L"normal.bin",16384,20000));EnterCriticalSection(&A.lock);CHECK("ordinary catch-up preserves selected identity IDs",child(root,L"normal.bin")==id&&resets==before);LeaveCriticalSection(&A.lock);
 wchar_t from[32768],to[32768];path_for_fixture(from,L"normal.bin");path_for_fixture(to,L"renamed.bin");CHECK("owned file rename",MoveFileExW(from,to,0));CHECK("rename appears without a new full projection",wait_size(root,L"renamed.bin",16384,20000));EnterCriticalSection(&A.lock);uint32_t renamed=child(root,L"renamed.bin");wchar_t *actual=renamed<A.model.count?space_model_path(&A.model,renamed,L"C:\\"):NULL;CHECK("renamed result has exact reveal/preview path",actual&&!wcscmp(actual,to));free(actual);LeaveCriticalSection(&A.lock);
 if(A.visible)ResetEvent(A.visible);uint64_t until=GetTickCount64()+10000;while(A.model.phase!=NTFS_PAUSED&&GetTickCount64()<until)pump(200);CHECK("hidden analyzer pauses journal polling",A.model.phase==NTFS_PAUSED&&A.thread);CHECK("owned hidden change",write_fixture(L"renamed.bin",8192));pump(1500);EnterCriticalSection(&A.lock);CHECK("hidden view retains its previous estimate",renamed<A.model.count&&A.model.nodes[renamed].sum.logical==16384);LeaveCriticalSection(&A.lock);SetEvent(A.visible);CHECK("show catches up changes made while hidden",wait_size(root,L"renamed.bin",8192,20000));CHECK("show resumes a live estimate",live_wait(10000));
 path_for_fixture(from,L"alias.bin");CHECK("remove owned hard link",DeleteFileW(from));until=GetTickCount64()+15000;while(GetTickCount64()<until){EnterCriticalSection(&A.lock);int gone=child(root,L"alias.bin")==SP_NONE;LeaveCriticalSection(&A.lock);if(gone)break;pump(200);}EnterCriticalSection(&A.lock);CHECK("removed aliases leave totals and views",child(root,L"alias.bin")==SP_NONE&&A.model.nodes[root].sum.logical==8195&&A.model.nodes[root].sum.allocated==8192);LeaveCriticalSection(&A.lock);
 EnterCriticalSection(&A.lock);uint32_t nested=child(root,L"nested"),note=child(nested,L"note.md");LeaveCriticalSection(&A.lock);path_for_fixture(to,L"target");CHECK("owned destination folder created",CreateDirectoryW(to,NULL));CHECK("new parent reaches incremental model",wait_size(root,L"target",0,15000));EnterCriticalSection(&A.lock);uint32_t target=child(root,L"target");LeaveCriticalSection(&A.lock);path_for_fixture(from,L"nested");path_for_fixture(to,L"target\\nested-moved");CHECK("owned directory moved between parents",MoveFileExW(from,to,0));CHECK("directory move preserves aggregate child bytes",wait_size(target,L"nested-moved",3,15000));EnterCriticalSection(&A.lock);uint32_t moved=child(target,L"nested-moved"),moved_note=child(moved,L"note.md");wchar_t *moved_path=moved_note<A.model.count?space_model_path(&A.model,moved_note,L"C:\\"):NULL;path_for_fixture(to,L"target\\nested-moved\\note.md");CHECK("directory move keeps child identity and exact ancestry",moved==nested&&moved_note==note&&moved_path&&!wcscmp(moved_path,to));free(moved_path);LeaveCriticalSection(&A.lock);
 path_for_fixture(from,L"renamed.bin");path_for_fixture(to,L"target\\alias-again.bin");CHECK("owned cross-folder hard link created",CreateHardLinkW(to,from,NULL));CHECK("new hard link reaches incremental model",wait_size(target,L"alias-again.bin",8192,15000));EnterCriticalSection(&A.lock);CHECK("incremental alias retains unique allocation",A.model.nodes[root].sum.logical==16387&&A.model.nodes[root].sum.allocated==8192&&A.model.nodes[root].sum.hardlinks==1);LeaveCriticalSection(&A.lock);

}
static void test_ntfs_panel_pause_reopen_cache_and_close(void){LONG seen=cached_seen;HANDLE child=OpenProcess(SYNCHRONIZE|PROCESS_QUERY_LIMITED_INFORMATION,FALSE,A.model.backend_pid);CHECK("worker exposes an observable owned process",child!=NULL);activate(15,0);uint64_t until=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<until)pump(100);if(child){CHECK("owned elevated process exits after Pause",WaitForSingleObject(child,5000)==WAIT_OBJECT_0);CloseHandle(child);}CHECK("Pause terminates only the owned worker",!A.thread&&A.model.state==SP_STOPPED&&A.model.phase==NTFS_PAUSED);uint64_t start=GetTickCount64();activate(15,0);CHECK("Refresh reopens a live cached model",live_wait(180000));CHECK("reopen actually loaded the production cache",cached_seen>seen);printf("cached_panel_ready_ms=%llu\n",(unsigned long long)(GetTickCount64()-start));stop();until=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<until)pump(100);CHECK("final panel cancellation drains worker ownership",!A.thread);}
int wmain(int argc,wchar_t **argv){if(argc!=2||wcslen(argv[1])>32000)return 2;wcscpy(fixture,argv[1]);if(!CreateDirectoryW(fixture,NULL))return 3;wchar_t path[32768],target[32768];path_for_fixture(path,L"nested");if(!CreateDirectoryW(path,NULL)||!write_fixture(L"normal.bin",65536)||!write_fixture(L"nested\\note.md",3))return 3;path_for_fixture(path,L"alias.bin");path_for_fixture(target,L"normal.bin");if(!CreateHardLinkW(path,target,NULL))return 3;wchar_t cachebase[32768];swprintf(cachebase,32768,L"%ls-cache",fixture);if(!CreateDirectoryW(cachebase,NULL))return 3;SetEnvironmentVariableW(L"LOCALAPPDATA",cachebase);
 InitializeCriticalSection(&A.lock);A.dpi=96;A.shown=1;A.selected=SP_NONE;A.in=GetStdHandle(STD_INPUT_HANDLE);A.out=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);A.cancel=CreateEventW(NULL,TRUE,FALSE,NULL);A.visible=CreateEventW(NULL,TRUE,TRUE,NULL);A.expanded=calloc(SP_NTFS_LIMIT,1);A.hwnd=CreateWindowExW(0,L"STATIC",L"Owned NTFS analyzer acceptance",WS_POPUP,0,0,0,0,NULL,NULL,GetModuleHandleW(NULL),NULL);fonts();HANDLE section=CreateFileMappingW(INVALID_HANDLE_VALUE,NULL,PAGE_READWRITE,0,520*820*8,NULL);if(!map(section,520,820))return 4;
 test_ntfs_panel_initial_model_and_views();if(!failed){test_ntfs_panel_live_updates_and_hidden_pause();test_ntfs_panel_pause_reopen_cache_and_close();}stop();uint64_t end=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<end)pump(100);if(A.thread)return 5;
 CHECK("query worker drained before NTFS panel destruction",query_shutdown(3000));CloseHandle(A.out);CloseHandle(A.cancel);CloseHandle(A.visible);space_model_free(&A.model);free(A.rows);free(A.expanded);free(A.root);if(A.shared)UnmapViewOfFile(A.shared);if(A.section)CloseHandle(A.section);if(A.bitmap){SelectObject(A.dc,A.original);DeleteObject(A.bitmap);}if(A.dc)DeleteDC(A.dc);if(A.font)DeleteObject(A.font);if(A.bold)DeleteObject(A.bold);if(A.small)DeleteObject(A.small);DestroyWindow(A.hwnd);DeleteCriticalSection(&A.lock);printf("%d passed, %d failed; 3 NTFS panel selectors; owned fixtures retained\n",passed,failed);return failed?1:0;}
